def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point instance to dehydrate.
    :type value: Point
    :return: A serializable representation of the point.
    :rtype: dict
    """
    if value is None:
        return None
    # Attempt to extract common point attributes
    try:
        return {"x": value.x, "y": value.y, "z": value.z}
    except AttributeError:
        # Fallback: use the object's __dict__ if available
        if hasattr(value, "__dict__"):
            return {k: v for k, v in value.__dict__.items() if not k.startswith("_")}
        # As a last resort, try to convert to a tuple
        try:
            return tuple(value)
        except Exception:
            # If all else fails, return the string representation
            return str(value)

