def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key.
    Keys provided in the items that are not in the record will be
    inserted with a value of None; indexes provided that are out of
    bounds will trigger an IndexError.
    """
    # If no keys are specified, return all key/value pairs
    if not keys:
        return {k: self._data.get(k) for k in self._keys}

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index access
            if key < 0 or key >= len(self._keys):
                raise IndexError(f"Index {key} out of bounds")
            k = self._keys[key]
            result[k] = self._data.get(k)
        else:
            # Key access
            if key in self._data:
                result[key] = self._data[key]
            else:
                result[key] = None
    return result

