def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    attrs = {}
    def __init__(self, x, y, srid=None, **kwargs):
        # Initialize the base Point class
        super(self.__class__, self).__init__(x, y)
        # Set any additional fields passed in kwargs
        for f in fields:
            setattr(self, f, kwargs.get(f))
        # Assign SRID if provided or from the mapping
        if srid is not None:
            self.srid = srid
        elif name in srid_map:
            self.srid = srid_map[name]
    attrs['__init__'] = __init__
    return type(name, (Point,), attrs)

