def parse_version(s: str) -> tuple[int, ...]:
    parts = s.split('.')
    nums = []
    for part in parts:
        digits = ''.join(ch for ch in part if ch.isdigit())
        if digits:
            nums.append(int(digits))
    return tuple(nums)

