def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            k = key(self, *args, **kwargs)
            if lock:
                lock.acquire()
                try:
                    try:
                        return cache[k]
                    except KeyError:
                        pass
                finally:
                    lock.release()
            else:
                try:
                    return cache[k]
                except KeyError:
                    pass
            result = func(self, *args, **kwargs)
            if lock:
                lock.acquire()
                try:
                    cache[k] = result
                finally:
                    lock.release()
            else:
                cache[k] = result
            return result
        return wrapper
    return decorator

