def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        # Keep tuples (implements specs) as a single item
        if isinstance(item, tuple):
            output.append(item)
        # Expand lists, sets, and frozensets into individual items
        elif isinstance(item, (list, set, frozenset)):
            output.extend(item)
        # Keep strings and bytes as individual items
        elif isinstance(item, (str, bytes)):
            output.append(item)
        else:
            # Try to detect other iterables (but not strings)
            try:
                iter(item)
            except TypeError:
                output.append(item)
            else:
                output.extend(item)
    return output

