def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # If error indices are stored in a dictionary keyed by coordinate name
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, dict):
        try:
            return self._err_indices[coord_name]
        except KeyError:
            raise KeyError(f"Coordinate '{coord_name}' not found in error indices.")
    # If error indices are stored in a list and coordinate names are in a list
    if hasattr(self, "_err_indices") and hasattr(self, "_coord_names"):
        try:
            idx = self._coord_names.index(coord_name)
            return self._err_indices[idx]
        except ValueError:
            raise KeyError(f"Coordinate '{coord_name}' not found in coordinate names.")
    # If neither structure is present, raise an informative error
    raise AttributeError("Error indices are not defined in this object.")

