def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer schema dictionary from a Kubernetes manifest dictionary.
    All non-dict and non-list values are replaced with None. For the top-level dictionary
    (when first_level is True), the identifying fields ('apiVersion', 'kind', 'metadata')
    are copied from the original manifest.
    """
    def _process_list(lst):
        processed = []
        for elem in lst:
            if isinstance(elem, dict):
                processed.append(generate_default_observer_schema_dict(elem, first_level=False))
            elif isinstance(elem, list):
                processed.append(_process_list(elem))
            else:
                processed.append(None)
        return processed

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = _process_list(value)
        else:
            result[key] = None

    if first_level:
        for id_field in ("apiVersion", "kind", "metadata"):
            if id_field in manifest_dict:
                result[id_field] = manifest_dict[id_field]

    return result

