def format(self, sql, params):
    in_named = getattr(self.SQLParams, "in_style", None) == "named"
    out_named = getattr(self.SQLParams, "out_style", None) == "named"
    out_placeholder = getattr(self.SQLParams, "out_style", "?")
    # Ensure sql is a string for processing
    if isinstance(sql, bytes):
        sql_str = sql.decode("utf-8")
    else:
        sql_str = sql
    if in_named:
        # Find named placeholders of the form :name
        placeholders = []
        i = 0
        while i < len(sql_str):
            if sql_str[i] == ":":
                j = i + 1
                while j < len(sql_str) and (sql_str[j].isalnum() or sql_str[j] == "_"):
                    j += 1
                if j > i + 1:
                    name = sql_str[i + 1 : j]
                    placeholders.append((i, j, name))
                    i = j
                else:
                    i += 1
            else:
                i += 1
        # Build new SQL string
        new_sql_parts = []
        last = 0
        for start, end, name in placeholders:
            new_sql_parts.append(sql_str[last:start])
            if out_named:
                new_sql_parts.append(f":{name}")
            else:
                new_sql_parts.append(out_placeholder)
            last = end
        new_sql_parts.append(sql_str[last:])
        new_sql = "".join(new_sql_parts)
        # Build out parameters
        if out_named:
            out_params = {name: params[name] for _, _, name in placeholders}
        else:
            out_params = [params[name] for _, _, name in placeholders]
    else:
        # Ordinal placeholders: assume '?' for simplicity
        count = 0
        new_sql_parts = []
        last = 0
        i = 0
        while i < len(sql_str):
            if sql_str[i] == "?":
                count += 1
                new_sql_parts.append(sql_str[last:i])
                if out_named:
                    new_sql_parts.append(f":param{count}")
                else:
                    new_sql_parts.append(out_placeholder)
                last = i + 1
                i = last
            else:
                i += 1
        new_sql_parts.append(sql_str[last:])
        new_sql = "".join(new_sql_parts)
        # Build out parameters
        if out_named:
            out_params = {f"param{i+1}": params[i] for i in range(count)}
        else:
            out_params = list(params[:count])
    # Return the same type as input
    if isinstance(sql, bytes):
        return new_sql.encode("utf-8"), out_params
    return new_sql, out_params

