def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # If no path provided, try to use the object's root attribute
        if not path:
            path = getattr(self, "root", None)
        if not path or not os.path.isdir(path):
            return False
        # Basic OCFL structure checks
        if not os.path.exists(os.path.join(path, ".ocfl_root")):
            return False
        if not os.path.exists(os.path.join(path, ".ocfl_version")):
            return False
        return True
    except Exception:
        return False

