    # Check that the inventory identifiers match
    if getattr(prior, "inventory_id", None) != getattr(self, "inventory_id", None):
        raise ValueError("inventory_id mismatch between current and prior inventory")

    # Ensure both inventories have a version attribute
    if getattr(prior, "version", None) is None or getattr(self, "version", None) is None:
        raise ValueError("both inventories must have a 'version' attribute")

    # Prior version must be strictly older
    if prior.version >= self.version:
        raise ValueError("prior inventory version must be older than current inventory version")

    # Ensure both inventories have a timestamp attribute
    if getattr(prior, "timestamp", None) is None or getattr(self, "timestamp", None) is None:
        raise ValueError("both inventories must have a 'timestamp' attribute")

    # Prior timestamp must not be newer than current
    if prior.timestamp > self.timestamp:
        raise ValueError("prior inventory timestamp must not be newer than current inventory timestamp")

    # Optional: verify that prior's data is a subset of current's data
    if hasattr(prior, "inventory_data") and hasattr(self, "inventory_data"):
        for key, val in prior.inventory_data.items():
            if key not in self.inventory_data or self.inventory_data[key] != val:
                raise ValueError(f"inventory data mismatch for key '{key}' between prior and current inventory")

    # If all checks pass, the prior inventory is considered valid
    return None

