def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Determine the pieces
    if isinstance(pieces, dict):
        major = pieces.get('major')
        minor = pieces.get('minor')
        patch = pieces.get('patch')
        prerelease = pieces.get('prerelease')
        build = pieces.get('build')
    elif isinstance(pieces, (list, tuple)):
        major = pieces[0] if len(pieces) > 0 else None
        minor = pieces[1] if len(pieces) > 1 else None
        patch = pieces[2] if len(pieces) > 2 else None
        prerelease = pieces[3] if len(pieces) > 3 else None
        build = pieces[4] if len(pieces) > 4 else None
    else:
        # If pieces is already a string, return it unchanged
        return str(pieces)

    # Helper to convert a part to string if not None
    def _s(part):
        return str(part) if part is not None else None

    major_s = _s(major)
    minor_s = _s(minor)
    patch_s = _s(patch)
    prerelease_s = _s(prerelease)
    build_s = _s(build)

    # Build the base version string
    if major_s is None:
        return ''
    base_parts = [major_s]
    if minor_s is not None:
        base_parts.append(minor_s)
    if patch_s is not None:
        base_parts.append(patch_s)
    base = '.'.join(base_parts)

    # Append prerelease and build if present
    if prerelease_s:
        base += '-' + prerelease_s
    if build_s:
        base += '+' + build_s

    # Render according to style
    if style == 'semver' or style == 'full':
        return base
    elif style == 'short':
        if minor_s is None:
            return major_s
        return f"{major_s}.{minor_s}"
    elif style == 'compact':
        # No separators at all
        compact = major_s
        if minor_s is not None:
            compact += minor_s
        if patch_s is not None:
            compact += patch_s
        if prerelease_s:
            compact += prerelease_s
        if build_s:
            compact += build_s
        return compact
    elif style == 'json':
        return {
            'major': major,
            'minor': minor,
            'patch': patch,
            'prerelease': prerelease,
            'build': build
        }
    else:
        # Default to semver
        return base

