def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Obtain an iterable of objects in the hierarchy
    if hasattr(self, "iter_objects"):
        objects_iter = self.iter_objects()
    else:
        objects_iter = getattr(self, "_objects", [])

    for obj in objects_iter:
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    obj.validate()
                elif hasattr(obj, "is_valid"):
                    if not obj.is_valid():
                        valid = False
                else:
                    # No validation method available
                    valid = False
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: validation failed for {obj}: {e}")

        if check_digests:
            try:
                if hasattr(obj, "check_digest"):
                    obj.check_digest()
                elif hasattr(obj, "digest") and hasattr(obj, "data"):
                    import hashlib
                    h = hashlib.sha256()
                    h.update(obj.data)
                    if h.hexdigest() != obj.digest:
                        valid = False
                else:
                    # No digest check method available
                    valid = False
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: digest check failed for {obj}: {e}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

