def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value) tuples, deep merging MappingNode values for duplicate keys.
    """
    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            existing_key_node, existing_value_node = merged_dict[key]
            # If both values are MappingNode, deep merge them
            if isinstance(existing_value_node, MappingNode) and isinstance(value_node, MappingNode):
                # Merge the mapping node values recursively
                merged_mapping = deep_merge_nodes(existing_value_node.value + value_node.value)
                merged_node = MappingNode(tag=existing_value_node.tag, value=merged_mapping)
                merged_dict[key] = (existing_key_node, merged_node)
            else:
                # For non-mapping or mixed types, last value wins
                merged_dict[key] = (existing_key_node, value_node)
        else:
            merged_dict[key] = (key_node, value_node)
    return list(merged_dict.values())

