    """
    Merge a list of (ScalarNode, value) tuples, deep merging MappingNode values for duplicate keys.
    """
    from collections import OrderedDict

    def merge_mapping_nodes(map1, map2):
        """
        Merge two MappingNode objects, returning a new MappingNode with merged content.
        """
        # Build a dict from map1's value list
        merged_dict = OrderedDict()
        for k, v in map1.value:
            merged_dict[k.value] = (k, v)
        # Merge map2's entries
        for k, v in map2.value:
