def load_configurations(config_filenames, overrides=None, resolve_env=True):
    config_dict = {}
    error_records = []
    for filename in config_filenames:
        try:
            import json, os, logging, re
            with open(filename, 'r') as f:
                content = f.read()
            parsed = json.loads(content)
            if overrides:
                parsed.update(overrides)
            if resolve_env:
                def replace_env(obj):
                    if isinstance(obj, dict):
                        return {k: replace_env(v) for k, v in obj.items()}
                    elif isinstance(obj, list):
                        return [replace_env(v) for v in obj]
                    elif isinstance(obj, str):
                        pattern = re.compile(r'\$\{([^}]+)\}')
                        def repl(match):
                            var = match.group(1)
                            return os.getenv(var, match.group(0))
                        return pattern.sub(repl, obj)
                    else:
                        return obj
                parsed = replace_env(parsed)
            config_dict[filename] = parsed
        except Exception as e:
            record = logging.LogRecord(
                'load_configurations',
                logging.ERROR,
                filename,
                0,
                f'Error loading {filename}: {e}',
                None,
                None
            )
            error_records.append(record)
    return config_dict, error_records

