    cls = candidate if isinstance(candidate, type) else type(candidate)

    # If iface is a class (including ABCs), use subclass logic
    if isinstance(iface, type):
        # Basic subclass check
        if not issubclass(cls, iface):
            return False

        # If not tentative, ensure all abstract methods are implemented
        if not tentative:
            abstract = getattr(iface, "__abstractmethods__", set())
            if abstract:
                # Check that each abstract method is present on the candidate
                for name in abstract:
                    if not hasattr(cls, name):
                        return False
