    Try to identify whether this is a Matrix request
    """
    # Helper to get attribute or dict key
    def get_attr(obj, name, default=None):
        if isinstance(obj, dict):
            return obj.get(name, default)
        return getattr(obj, name, default)

    # Extract path or URL
    path = get_attr(request, "path") or get_attr(request, "url")
    if not path:
        return False

    # Normalize path
    if isinstance(path, str):
        path = path.lower()
    else:
        return False

    # Check for Matrix path prefix
    if path.startswith("/_matrix") or "/_matrix/" in path:
        return True

    # Check headers for Matrix specific markers
    headers = get_attr(request, "headers", {})
    if isinstance(headers, dict):
        for key, value in headers.items():
            if key.lower() == "x-matrix-request":
                return True
            if key.lower() == "content-type" and "application/json" in value.lower():
                # Common Matrix content type
                return True

    return False

