def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags: Set[str] = set()
    # Pattern to match fenced code blocks (```) with any content inside
    code_block_pattern = re.compile(r'```.*?```', re.DOTALL)
    # Pattern to match tags of the form #word
    tag_pattern = re.compile(r'#(\w+)')

    def _replace_in_segment(segment: str) -> str:
        def repl(match: re.Match) -> str:
            tag_word = match.group(1)
            tags.add('#' + tag_word)
            if replacer:
                return replacer(tag_word)
            return match.group(0)
        return tag_pattern.sub(repl, segment)

    result_parts = []
    last_end = 0
    for m in code_block_pattern.finditer(text):
        # Process text before the code block
        before = text[last_end:m.start()]
        result_parts.append(_replace_in_segment(before))
        # Append the code block unchanged
        result_parts.append(m.group(0))
        last_end = m.end()
    # Process any remaining text after the last code block
    after = text[last_end:]
    result_parts.append(_replace_in_segment(after))

    return tags, ''.join(result_parts)

