def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # A tag must be non-empty, contain only lowercase letters, digits, or hyphens,
    # start and end with an alphanumeric character, and be at most 30 characters long.
    if not tag:
        return False
    if len(tag) > 30:
        return False
    # Ensure all characters are lowercase letters, digits, or hyphens
    for ch in tag:
        if not (ch.islower() or ch.isdigit() or ch == '-'):
            return False
    # Must start and end with an alphanumeric character
    if not (tag[0].isalnum() and tag[-1].isalnum()):
        return False
    return True

