def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _parse_json(doc: str) -> Dict:
        data = json.loads(doc)
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        if isinstance(aliases, str):
            aliases = [aliases]
        links = data.get("links", [])
        parsed_links = []
        for link in links:
            if isinstance(link, dict):
                rel = link.get("rel")
                href = link.get("href")
                type_ = link.get("type")
                if rel and href:
                    parsed_links.append({"rel": rel, "type": type_, "href": href})
        return {"subject": subject, "aliases": aliases, "links": parsed_links}

    def _strip_ns(tag: str) -> str:
        return tag.split("}", 1)[-1] if "}" in tag else tag

    def _parse_xrd(doc: str) -> Dict:
        root = ET.fromstring(doc)
        subject = None
        aliases = []
        links = []
        for elem in root.iter():
            tag = _strip_ns(elem.tag)
            if tag == "subject":
                subject = elem.text
            elif tag == "alias":
                if elem.text:
                    aliases.append(elem.text)
            elif tag == "link":
                rel = elem.attrib.get("rel")
                href = elem.attrib.get("href")
                type_ = elem.attrib.get("type")
                if rel and href:
                    links.append({"rel": rel, "type": type_, "href": href})
        return {"subject": subject, "aliases": aliases, "links": links}

    # Try JSON first
    try:
        return _parse_json(document)
    except json.JSONDecodeError:
        pass

    # Fallback to XRD
    try:
        return _parse_xrd(document)
    except ET.ParseError as exc:
        raise ValueError("Invalid webfinger document") from exc
    except Exception as exc:
        raise ValueError("Failed to parse webfinger document") from exc

