def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        return parser_dict

    processed_files = set()

    def _merge(target, source):
        """Recursively merge source dict into target dict."""
        for key, value in source.items():
            if key in target:
                if isinstance(target[key], dict) and isinstance(value, dict):
                    _merge(target[key], value)
                else:
                    target[key] = value
            else:
                target[key] = value

    def _process(spec_dict):
        if not isinstance(spec_dict, dict):
            return
        include = spec_dict.pop('include', None)
        if include is None:
            return

        # Normalize include to a list of (group_name, path) tuples
        includes = []
        if isinstance(include, dict):
            for group_name, path in include.items():
                includes.append((group_name, path))
        elif isinstance(include, (list, tuple)):
            for path in include:
                includes.append((None, path))
        else:
            includes.append((None, include))

        for group_name, inc_path in includes:
            if inc_path in processed_files:
                continue
            processed_files.add(inc_path)
            # Load the included spec; assume self._load_spec exists
            inc_spec = self._load_spec(inc_path)
            _process(inc_spec)
            if group_name is None:
                _merge(spec_dict, inc_spec)
            else:
                spec_dict[group_name] = inc_spec

    _process(parser_dict)
    return parser_dict

