def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.
    Returns a dictionary mapping argument names to their resolved default values.
    """
    defaults = {}
    # Iterate over argument specifications
    for arg in self.spec.get('arguments', []):
        name = arg.get('name')
        if not name:
            continue

        # Start with the explicit default from the spec
        value = arg.get('default')

        # If no explicit default, try environment variable if specified
        if value is None and 'env' in arg:
            try:
                import os
                value = os.getenv(arg['env'])
            except Exception:
                value = None

        # If still no value, try a config source if available
        if value is None:
            # Prefer a dict-like config
            if hasattr(self, 'config'):
                if isinstance(self.config, dict):
                    value = self.config.get(name)
                else:
                    value = getattr(self.config, name, None)

        defaults[name] = value
    return defaults

