def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    # Build the base command
    cmd = ["ansible-playbook", playbook_path]

    # Add inventory from the workspace if available
    inventory = getattr(ir_workspace, "inventory_path", None)
    if inventory:
        cmd.extend(["-i", inventory])

    # Add verbosity flags
    if verbose:
        if isinstance(verbose, int):
            cmd.append("-" + "v" * verbose)
        else:
            # assume string like "v" or "vv"
            cmd.append("-" + str(verbose))

    # Add any additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
            else:
                cmd.extend([key, str(value)])

    # Add extra variables
    if extra_vars:
        import json
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    # Execute the command
    import subprocess
    result = subprocess.run(cmd, capture_output=True, text=True)

    # Optionally print output if verbose
    if verbose:
        import sys
        print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)

    # Raise an error if the command failed
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}"
        )

    return result

