def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Mapping of parser names to expected argument types
    type_map = {
        'main': {
            'debug': bool,
            'timeout': int,
            'threshold': float,
            'names': list,
        },
        'virsh': {
            'force': bool,
            'timeout': int,
        },
        'ospd': {
            'debug': bool,
            'max_retries': int,
        },
    }

    parser_map = type_map.get(parser_name, {})

    for key, value in list(values_dict.items()):
        if value is None:
            continue

        # Determine target type
        target_type = parser_map.get(key)

        # If no explicit type, try to infer from the string value
        if target_type is None and isinstance(value, str):
            val = value.strip()
            # Boolean detection
            if val.lower() in ('true', 'false', '1', '0', 'yes', 'no', 'y', 'n'):
                target_type = bool
            # List detection (comma separated)
            elif ',' in val:
                target_type = list
            else:
                # Integer detection
                try:
                    int(val)
                    target_type = int
                except ValueError:
                    # Float detection
                    try:
                        float(val)
                        target_type = float
                    except ValueError:
                        target_type = str

        # If still no type, skip conversion
        if target_type is None:
            continue

        # Skip if already correct type
        if isinstance(value, target_type):
            continue

        try:
            if target_type is bool:
                if isinstance(value, str):
                    v = value.strip().lower()
                    if v in ('true', '1', 'yes', 'y'):
                        values_dict[key] = True
                    elif v in ('false', '0', 'no', 'n'):
                        values_dict[key] = False
                    else:
                        values_dict[key] = bool(value)
                else:
                    values_dict[key] = bool(value)
            elif target_type is int:
                values_dict[key] = int(value)
            elif target_type is float:
                values_dict[key] = float(value)
            elif target_type is list:
                if isinstance(value, str):
                    values_dict[key] = [v.strip() for v in value.split(',') if v.strip()]
                else:
                    values_dict[key] = list(value)
            else:
                values_dict[key] = target_type(value)
        except Exception:
            # If conversion fails, leave the original value
            pass

