def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Find the spec file
    spec_file = None
    for fname in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_file = path
            break
    if not spec_file:
        return {}

    # Load the spec
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith((".yaml", ".yml")):
                if yaml is None:
                    return {}
                data = yaml.safe_load(f)
            else:
                data = json.load(f)
    except Exception:
        return {}

    # Flatten nested dicts
    def _flatten(d, parent_key=""):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    if isinstance(data, dict):
        return _flatten(data)
    return {}

